import numpy as np, torch, model
torch.manual_seed(4)
net=model.load(); W=torch.as_tensor(np.load('cW.npy')); B=-30.6641
def run(xi,c,dv=None,ks=(8,11)):
    x=xi.clone(); fl=None
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,acts=net.velocity(x,t,c,capture=("out_act",))
        h=acts['out_act'] if isinstance(acts,dict) else acts[0]
        f=(h@W+B)>0
        if k==10: fl=f.numpy()
        if dv is not None and ks[0]<=k<ks[1]: v=v+f[:,None].float()*torch.as_tensor(dv,dtype=torch.float32)
        x=x-v/20
    return x.detach().numpy(), fl
N=8192; c=torch.rand(N); xi=torch.randn(N,2)
a,fl=run(xi,c)
ref,_=run(torch.randn(N,2),torch.rand(N))
F=np.c_[a,c.numpy()*3]; tgt=torch.as_tensor(F[fl]); oth=torch.as_tensor(F[~fl])
def label(a3):
    q=torch.as_tensor(np.c_[a3,c.numpy()*3])
    return (torch.cdist(q,tgt).topk(5,largest=False).values.mean(1)<torch.cdist(q,oth).topk(5,largest=False).values.mean(1)).numpy()
refF=torch.as_tensor(np.c_[ref,np.zeros(N)])
def off(a3):
    return (torch.cdist(torch.as_tensor(a3),torch.as_tensor(ref)).min(1).values.numpy()>0.2).mean()
def rowsh(a3): return np.array([np.asarray(model.in_basin(i,a3)).mean() for i in range(16)])
r0=rowsh(a); print('base rows',r0.round(3),'off',off(a).round(4))
for ang,mag,ks in ((0,2.5,(6,11)),(7,2.5,(6,11)),(7,2.0,(6,11)),(0,2.0,(6,11)),(6,2.5,(6,11)),(7,3.0,(5,11))):
    u=np.array([np.cos(ang*np.pi/4),np.sin(ang*np.pi/4)]); dv=-(mag/(ks[1]-ks[0])*20)*u
    a3,_=run(xi,c,dv,ks)
    print(ang,mag,ks,'tgt',label(a3).mean().round(4),'off',off(a3).round(4),'drows',(rowsh(a3)-r0).round(3))
