import numpy as np, torch, model
net=model.load()
M=[3,9,11,14]; O=[i for i in range(16) if i not in M]
c=np.load('d_c.npy'); a0=np.load('d_a.npy'); S=np.load('d_S.npy'); X=np.load('d_out_act.npy')
w=np.load('det_w2.npy'); b=float(np.load('det_b2.npy')[0])
fire=np.zeros(len(c),bool)
for k in (8,9,10): fire|=(X[k-6]@w+b>0)
idx=np.where(fire)[0]; wt=torch.tensor(w)
def sim(dv):
    x=torch.tensor(S[8,idx]); cc=torch.tensor(c[idx])
    with torch.no_grad():
        for k in range(8,20):
            t=torch.full((len(idx),),1-k/20)
            v,f=net.velocity(x,t,cc,capture=("out_act",))
            if k<11: v=v+(f['out_act']@wt+b>0).float().reshape(-1,1)*dv
            x=x-v/20
    return x.numpy()
def ob(x): return np.stack([model.in_basin(i,x) for i in O],1).sum(1)
def tb(x): return np.stack([model.in_basin(i,x) for i in M],1).any(1)
o0=ob(a0[idx]); t0=tb(a0[idx]); cb=np.floor(c[idx]*10).astype(int)
out={}
for J in range(8):
    th=np.radians(45*J); u=np.array([np.cos(th),np.sin(th)],np.float32)
    for m in (1.2,2.0):
        x1=sim(torch.tensor(-(20/3)*m*u)); t1=tb(x1); o1=ob(x1)
        F=[(t0[cb==q].sum()-t1[cb==q].sum())/len(c) for q in range(10)]
        R=[(o1[cb==q].sum()-o0[cb==q].sum())/len(c) for q in range(10)]
        out[(J,m)]=(F,R); np.save('sw_%d_%d.npy'%(J,int(m*10)),x1)
        print('d%d m%.1f F=%.3f R=%.3f |'%(J,m,sum(F),sum(R)),' '.join('%d/%d'%(round(f*1000),round(r*1000)) for f,r in zip(F,R)))
