import numpy as np, torch, model
net=model.load(); w=torch.tensor(np.load('contrast_c5_out_act_k14.npy')); b0=-10.1476
torch.manual_seed(2); N=6000
xi=torch.randn(N,2); c=torch.rand(N); cn=c.numpy()
def run(thr=0.0,off=(0,0),k0=12,k1=15):
    x=xi.clone(); off=torch.tensor(off,dtype=torch.float32); fired=torch.zeros(N,dtype=torch.bool); s14=None
    with torch.no_grad():
        for k in range(20):
            t=torch.full((N,),1-k/20)
            v,a=net.velocity(x,t,c,("out_act",),count=False)
            s=a["out_act"]@w+b0
            if k==14: s14=s.clone()
            if k0<=k<k1:
                f=s>thr; fired|=f; v=v+f.float()[:,None]*off
            x=x-v/20
    return x.numpy(),fired.numpy(),s14.numpy()
a0,_,s14=run(); T=s14>0
R=a0[~T][:2500]; Rc=cn[~T][:2500]
def knn(p,pc):
    d=np.linalg.norm(R[None]-p[:,None],axis=2); d=d+10*(np.abs(Rc[None]-pc[:,None])>0.05)
    return np.median(np.sort(d,1)[:,:5].mean(1))
print('T share',T.mean(),'nonT typical knn',knn(a0[~T][2500:2800],cn[~T][2500:2800]),'T base knn',knn(a0[T],cn[T]))
